// The portal's page and panel contract, copied.
//
// `nanoportal/web/src/portal/contract.ts` is the source of truth; this build keeps
// its own copy so the two do not import each other. A field added there must be
// copied here before a page or panel may rely on it — the plugin's `tsc` fails
// otherwise, which is the check that keeps them in step.
//
// Generated by `nanoportal/web/scripts/sync-contract.mjs`; do not edit by hand.
//
// `DockId` is inlined: a plugin must not import the shell's source tree.

// The plugin contract, in the shape the frontend design calls for: types and
// constants only, no implementation and no data access.
//
// A plugin contributes panels and pages. The shell names the contract version it
// speaks; a manifest from another version is refused rather than half-loaded, and
// every plugin is expected to keep working against the previous version so the
// shell can be rolled back alone.
//
// This module is the seed of `@nanosec/portal-contract`. It becomes a package
// when the second plugin ships; until then a path import keeps the build free of
// package-manager changes.

import type { ChangeEvent, ComponentType, ReactNode } from 'react'

/** The docks a panel may open in; the shell owns the list. */
type DockId = 'left' | 'center' | 'right' | 'bottom'

/** The plugin contract this shell speaks. Bump only with a release window. */
export const CONTRACT_VERSION = 1

/** A string per language tag, e.g. `{ "zh-CN": "作品库", en: "Library" }`. */
export type LocalizedText = Record<string, string>

/**
 * Icons a manifest may name. A remote cannot ship a React component, and an
 * arbitrary SVG from the network would be a styling and safety problem, so the
 * vocabulary is closed and mapped to the shell's own icons.
 */
export const PANEL_ICONS = [
  'layers',
  'file-text',
  'folder',
  'layout-grid',
  'book-open',
  // The console's menu icons. A navigation entry names one of these instead of
  // shipping a component: a remote cannot hand over React, and an arbitrary SVG
  // would be a styling and safety problem.
  'activity',
  'bell',
  'blocks',
  'bot',
  'boxes',
  'cpu',
  'key-round',
  'layout-dashboard',
  'message-square',
  'mic',
  'scroll-text',
  'sliders-horizontal',
  'users',
] as const
export type PanelIcon = (typeof PANEL_ICONS)[number]

/**
 * How a panel's content is produced.
 *
 * - `module` is a component the shell loads at runtime (Module Federation
 *   remote). It renders inside the shell's React tree, so it inherits theme,
 *   i18n and the drag/resize behaviour.
 * - `frame` carries an application that cannot share the shell's stack. It is
 *   the boundary for heterogeneous or third-party UIs.
 */
export type PanelMount =
  | { kind: 'module'; module: string; export: string }
  | { kind: 'frame'; url: string }

export type PanelContribution = {
  /** Panel id inside its plugin; the shell prefixes it with the plugin id. */
  id: string
  title: LocalizedText
  icon: PanelIcon
  /** Where a fresh browser puts the panel; the user can move it afterwards. */
  slot: DockId
  mount: PanelMount
}

/** The parts of the stored session a page may read or patch. */
export type SessionSnapshot = {
  user_id: string
  role?: string
  display_name?: string
  /** Set by an administrator's password reset; the shell forces the change page. */
  must_change_password?: boolean
  /**
   * The tokens a sign-in just issued. The shell owns the stored session, so a page
   * that signs in hands them over rather than writing storage itself — without them
   * the "session" would have an identity but no credential.
   */
  access_token?: string
  refresh_token?: string
}

/**
 * What a panel gets from the shell. Every field is data the shell already owns:
 * a plugin never reaches into the shell's storage, router or theme.
 */
export type PortalContext = {
  token: string
  userId: string
  /** The signed-in account, as the shell stores it (empty user id on the login screen). */
  session: SessionSnapshot
  /** The route's query string, decoded (`?next=/agent` → `{ next: "/agent" }`). */
  query: Record<string, string>
  locale: string
  theme: 'light' | 'dark'
  navigate: (path: string) => void
  openPanel: (panelId: string) => void
  /** The agent the shell is focused on; a workbench panel always gets one. */
  agentId?: string
}

/**
 * What a workbench panel gets: the panel context plus the shell's strings, kit,
 * data client and notifications. A panel lives in the shell's tree like a page, so
 * it needs the same services — without the route plumbing a page has.
 */
export type PanelContext = PortalContext & {
  t: (key: string, options?: Record<string, unknown>) => string
  ui: PortalUIText
  api: PortalApi
  toast: PortalToast
}

/**
 * A whole page a plugin contributes: the shell mounts it at `path` instead of
 * its own built-in page for that route.
 *
 * A page is the same kind of contribution as a panel — a module the shell loads
 * at runtime — with one difference: it owns the route. That is what lets a
 * module ship a screen (the work library, the account pages) without the shell
 * importing its code, and without an iframe boundary it does not need.
 */
export type PageContribution = {
  /** Page id inside its plugin; the shell prefixes it with the plugin id. */
  id: string
  /** The shell route this page answers, e.g. `/artifacts`. */
  path: string
  title: LocalizedText
  mount: PanelMount
}

/**
 * One entry in the shell's navigation.
 *
 * The menu belongs to the module that owns the pages: without this a new screen
 * would need a shell release to be reachable. What stays in the shell is the
 * policy — `section` names one of the shell's sections, and the shell decides
 * which roles may see it. A manifest that names no section gets the narrowest
 * one (`admin`), never "everybody".
 *
 * `parent` nests the entry under another one. The admin console's layout is the
 * shell's, so a plugin's entries hang under `admin` and the shell renders them in
 * its own chrome; a top-level entry would be its own route.
 */
export type NavContribution = {
  /** Nav id inside its plugin; the shell prefixes it with the plugin id. */
  id: string
  /** Parent nav id (`"admin"` nests under the console's layout). Empty = top level. */
  parent?: string
  /** Absolute route this entry opens; the page of the same path renders there. */
  path: string
  title: LocalizedText
  icon: PanelIcon
  /** The shell section whose roles gate this entry. Unknown sections see nobody. */
  section?: string
  /** Position among its siblings; ties keep manifest order. */
  order: number
}

/**
 * The shell's component kit, handed to a page through its context.
 *
 * A module front end shares the shell's React instance but not its source, so a
 * page cannot import the design system. Passing the components through the
 * context keeps one implementation of each control (and one set of compiled
 * styles) while the page stays in its own application.
 *
 * The prop types are structural on purpose: they are the contract, not a
 * re-export of the shell's internals. A prop a page needs must be added here
 * before any page may rely on it.
 */
type Children = { children?: ReactNode }

export type PortalUIText = {
  Button: ComponentType<
    Children & {
      variant?: 'default' | 'outline' | 'ghost' | 'secondary' | 'destructive'
      size?: 'default' | 'sm' | 'lg' | 'icon'
      type?: 'button' | 'submit'
      className?: string
      disabled?: boolean
      title?: string
      onClick?: () => void
    }
  >
  Input: ComponentType<{
    type?: string
    id?: string
    /** React accepts a number for a controlled input; the field renders it as text. */
    value?: string | number
    placeholder?: string
    'aria-label'?: string
    spellCheck?: boolean | 'true' | 'false'
    /** `numeric`, `decimal`, `email`, … — the keyboard hint a mobile browser reads. */
    inputMode?: 'none' | 'text' | 'numeric' | 'decimal' | 'email' | 'tel' | 'search' | 'url'
    step?: string
    className?: string
    disabled?: boolean
    required?: boolean
    readOnly?: boolean
    autoComplete?: string
    autoFocus?: boolean
    minLength?: number
    onChange?: (event: ChangeEvent<HTMLInputElement>) => void
  }>
  Card: ComponentType<Children & { className?: string }>
  CardHeader: ComponentType<Children & { className?: string }>
  CardTitle: ComponentType<Children & { className?: string }>
  CardDescription: ComponentType<Children & { className?: string }>
  CardContent: ComponentType<Children & { className?: string }>
  Badge: ComponentType<
    Children & {
      variant?: 'default' | 'secondary' | 'outline' | 'success' | 'warning' | 'danger' | 'info'
      className?: string
    }
  >
  Skeleton: ComponentType<{ className?: string }>
  EmptyState: ComponentType<{
    title: string
    description?: string
    icon?: ComponentType<{ className?: string }>
    action?: ReactNode
    className?: string
  }>
  Table: ComponentType<Children & { className?: string; stacked?: boolean }>
  TableHeader: ComponentType<Children & { className?: string }>
  TableBody: ComponentType<Children & { className?: string }>
  TableRow: ComponentType<Children & { className?: string; onClick?: () => void }>
  TableHead: ComponentType<Children & { className?: string }>
  TableCell: ComponentType<Children & { className?: string; label?: ReactNode; title?: string }>
  Pagination: ComponentType<{
    page: number
    pageSize: number
    total: number
    onPageChange: (page: number) => void
    onPageSizeChange?: (size: number) => void
  }>
  StatusBadge: ComponentType<{
    status: string
    /** Override the status→tone mapping (a health word that is not a status). */
    tone?: 'success' | 'warning' | 'danger' | 'neutral' | 'info'
    className?: string
    dotOnly?: boolean
  }>
  /** The shell's status→tone mapping, for a badge whose status is a domain word. */
  toneForStatus: (status: string) => 'success' | 'warning' | 'danger' | 'neutral' | 'info'
  /** A read-only JSON block, as the audit log shows one entry's detail. */
  JsonView: ComponentType<{ value: Record<string, unknown>; className?: string }>
  Select: ComponentType<{
    value: string
    onValueChange: (value: string) => void
    disabled?: boolean
    children?: ReactNode
  }>
  SelectTrigger: ComponentType<Children & { className?: string; disabled?: boolean; 'aria-label'?: string }>
  SelectValue: ComponentType<{ placeholder?: string }>
  SelectContent: ComponentType<Children & { className?: string }>
  SelectItem: ComponentType<Children & { value: string; disabled?: boolean }>
  PageHeader: ComponentType<{
    title: ReactNode
    subtitle?: ReactNode
    actions?: ReactNode
    backTo?: string
    backLabel?: ReactNode
    className?: string
  }>
  FormField: ComponentType<{ label: string; hint?: string; error?: string; className?: string; children: ReactNode }>
  MetricCard: ComponentType<{
    icon: ComponentType<{ className?: string }>
    label: string
    value?: ReactNode
    sub?: ReactNode
    loading?: boolean
    className?: string
  }>
  Tooltip: ComponentType<Children & { delayDuration?: number }>
  TooltipTrigger: ComponentType<Children & { asChild?: boolean }>
  TooltipContent: ComponentType<Children & { className?: string; sideOffset?: number }>
  ConfirmDialog: ComponentType<{
    open: boolean
    onOpenChange: (open: boolean) => void
    title: string
    description?: string
    confirmLabel?: string
    onConfirm: () => Promise<void> | void
    busy?: boolean
  }>
  Switch: ComponentType<{
    id?: string
    checked?: boolean
    onCheckedChange?: (checked: boolean) => void
    disabled?: boolean
    className?: string
    'aria-label'?: string
    'aria-readonly'?: boolean
  }>
  Tabs: ComponentType<
    Children & {
      /** Uncontrolled (the usual case) or controlled; the shell's tabs accept both. */
      defaultValue?: string
      value?: string
      onValueChange?: (value: string) => void
      orientation?: 'horizontal' | 'vertical'
      className?: string
    }
  >
  TabsList: ComponentType<Children & { className?: string }>
  TabsTrigger: ComponentType<Children & { value: string; className?: string; disabled?: boolean }>
  TabsContent: ComponentType<Children & { value: string; className?: string }>
  Separator: ComponentType<{ orientation?: 'horizontal' | 'vertical'; className?: string }>
  Spinner: ComponentType<{ label?: string; className?: string }>
  DropdownMenu: ComponentType<{
    open?: boolean
    onOpenChange?: (open: boolean) => void
    children?: ReactNode
  }>
  DropdownMenuTrigger: ComponentType<Children & { asChild?: boolean; className?: string }>
  DropdownMenuContent: ComponentType<Children & { align?: 'start' | 'center' | 'end'; className?: string }>
  DropdownMenuItem: ComponentType<
    Children & {
      className?: string
      disabled?: boolean
      onSelect?: (event: { preventDefault: () => void }) => void
    }
  >
  DropdownMenuLabel: ComponentType<Children & { className?: string }>
  DropdownMenuSeparator: ComponentType<{ className?: string }>
  /** A submenu: the agent list nests "move to group" under its row menu. */
  DropdownMenuSub: ComponentType<Children>
  DropdownMenuSubTrigger: ComponentType<Children & { className?: string; disabled?: boolean }>
  DropdownMenuSubContent: ComponentType<Children & { className?: string }>
  HeightResizeHandle: ComponentType<{
    value: number
    min: number
    max: number
    onChange: (value: number) => void
    expandBy?: 'up' | 'down'
    onReset?: () => void
    className?: string
    label?: string
    hint?: string
  }>
  Dialog: ComponentType<Children & { open: boolean; onOpenChange: (open: boolean) => void }>
  DialogContent: ComponentType<Children & { className?: string }>
  DialogHeader: ComponentType<Children & { className?: string }>
  DialogTitle: ComponentType<Children & { className?: string }>
  DialogDescription: ComponentType<Children & { className?: string }>
  DialogFooter: ComponentType<Children & { className?: string }>
  /**
   * The file browser, as a component.
   *
   * It is far too large to freeze as a prop list, and it belongs to this shell
   * until the workspace module ships its own; handing the component over keeps one
   * implementation while the page that embeds it lives elsewhere. When workspace
   * takes it over, only this reference changes.
   */
  FilePanel: ComponentType<{ agentId: string; allowUpload?: boolean }>
  Textarea: ComponentType<{
    value?: string
    id?: string
    rows?: number
    className?: string
    placeholder?: string
    readOnly?: boolean
    disabled?: boolean
    spellCheck?: boolean | 'true' | 'false'
    'aria-label'?: string
    onChange?: (event: ChangeEvent<HTMLTextAreaElement>) => void
  }>
}

/** What a page may ask the platform for; every call carries the caller's token. */
export type PortalApi = {
  get: <T>(path: string, base?: string) => Promise<T>
  post: <T>(path: string, body: unknown, base?: string) => Promise<T>
  put: <T>(path: string, body: unknown, base?: string) => Promise<T>
  patch: <T>(path: string, body: unknown, base?: string) => Promise<T>
  del: <T>(path: string, base?: string) => Promise<T>
  /** Hosts of the platform APIs, so a page never spells a URL itself. */
  bases: { portalConsole: string; admin: string; user: string; workspace: string; auth: string }
}

/**
 * Shell capabilities a page may invoke.
 *
 * These are features, not components: the agent editor is the portal's (it owns the
 * agent rows), so a page asks the shell to open it instead of rebuilding it. A
 * request names what to edit; the shell loads it and owns the dialog's lifetime.
 */
export type PortalFeatures = {
  /** Open the agent editor. With an id the shell loads that agent first. */
  openAgentForm: (request: { userId: string; agentId?: string; onSaved?: () => void }) => void
  /**
   * Drop the composer's cached voice settings.
   *
   * The console's dictation card and the composer read the same configuration; the
   * card lives in another module now, so it asks the shell to forget what it cached
   * instead of reaching into it.
   */
  refreshVoiceConfig: () => void
  /**
   * Store a freshly issued session. The shell owns the storage (and the rule that
   * another account signing in on this browser drops the previous one's caches), so
   * the login and registration pages ask it to sign in rather than writing it.
   */
  signIn: (session: SessionSnapshot) => void
  /** Patch the stored session (the forced password change clears its flag here). */
  patchSession: (patch: Partial<SessionSnapshot>) => void
}

/** Transient feedback, in the shell's own notification style. */
export type PortalToast = {
  success: (message: string) => void
  info: (message: string) => void
  warning: (message: string) => void
  error: (message: string) => void
}

/** What a page gets: the panel context plus the shell's kit, strings and data client. */
export type PageContext = PortalContext & {
  t: (key: string, options?: Record<string, unknown>) => string
  /** The route's parameters (`:id` and friends), read-only. */
  params: Record<string, string>
  /** Publish an entity name to the shell's breadcrumb; null clears it. */
  setCrumb: (label: string | null, title?: string) => void
  ui: PortalUIText
  api: PortalApi
  features: PortalFeatures
  toast: PortalToast
}

/** A page component, as exported by a `module` mount. */
export type PageComponent = ComponentType<{ ctx: PageContext }>

/** A panel component, as exported by a `module` mount. */
export type PanelComponent = ComponentType<{ ctx: PanelContext }>

/** What an application publishes at <base>/plugin.json. */
export type RemoteManifest = {
  contract: number
  plugin: string
  /** Remote entry of the module federation build, same-origin path. */
  entry: string
  panels: PanelContribution[]
  /** Routes this plugin takes over. Optional: a plugin may contribute panels only. */
  pages?: PageContribution[]
  /** Navigation entries. Optional: a plugin may contribute pages without a menu. */
  nav?: NavContribution[]
  /**
   * Components the shell may borrow, by role.
   *
   * The file browser is the one case: `filePanel` names the export a page renders
   * when it needs to show an agent's files. Naming it in the manifest keeps the
   * shell from hardcoding another module's module path, and lets the owner move
   * the component without a shell release.
   */
  provides?: Record<string, { module: string; export: string }>
}

/** The shell's own table: which plugins load, and which panels the shell ships. */
export type ShellManifest = {
  contract: number
  plugins: Record<string, ShellPluginEntry>
}

export type ShellPluginEntry = {
  impl?: string
  /** Same-origin path to the application's manifest (module plugins). */
  manifest?: string
  /** Panel ids this entry contributes, in activity-bar order (the shell). */
  panels?: string[]
}

export type ParseResult<T> = { ok: true; value: T } | { ok: false; error: string }
